(* [comment removed for export] *)
Lemma grow (fx : FPState) R M model LK Aw (n0 a1 s2 s7 : Z) :
  stok model LK Aw -> x = PM.VShort n0 -> n = 23 -> PmSpecs.PMSP.credit_le (scA (PQMA.pot_textM HV x)) cr0 ->
  getr R (reg 1) = Z_to_bv 64 0xf42dc ->
  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 o -> getr R (reg 9) = Z_to_bv 64 25 -> getr R (reg 10) = Z_to_bv 64 26 ->
  getr R (reg 18) = Z_to_bv 64 s2 -> getr R (reg 19) = Z_to_bv 64 26 -> getr R (reg 20) = Z_to_bv 64 0 -> getr R (reg 21) = Z_to_bv 64 22 -> getr R (reg 22) = Z_to_bv 64 0 ->
  getr R (reg 23) = Z_to_bv 64 s7 -> 0 <= s2 < 2 ^ 64 -> 0 <= s7 < 2 ^ 64 ->
  kept0 R -> saves M -> mem_ok M ->
  ri_inv HI LB FF LK cr0 Aw M (vml_of model) ->
