Definition srsv44_post (x x' : PM.vstr) : Prop :=
  match x with
  | PM.VShort _ => exists p, x' = PM.VLong 48 0 p
  | PM.VLong c _ _ => (45 <= c -> x' = x) /\ (c <= 44 -> exists p, x' = PM.VLong 48 0 p)
  end.
Section Specs.
Context {SCFG_P : ScfgP}.
