Lemma saves_of (M : word -> option byte) :
  L5.u64_at RSEGS M (S - 72) (bv_unsigned (getr R0 (reg 23))) -> L5.u64_at RSEGS M (S - 64) (bv_unsigned (getr R0 (reg 22))) ->
  L5.u64_at RSEGS M (S - 56) (bv_unsigned (getr R0 (reg 21))) -> L5.u64_at RSEGS M (S - 48) (bv_unsigned (getr R0 (reg 20))) ->
  L5.u64_at RSEGS M (S - 40) (bv_unsigned (getr R0 (reg 19))) -> L5.u64_at RSEGS M (S - 32) (bv_unsigned (getr R0 (reg 18))) ->
  L5.u64_at RSEGS M (S - 24) (bv_unsigned (getr R0 (reg 9))) -> L5.u64_at RSEGS M (S - 16) (bv_unsigned (getr R0 (reg 8))) ->
