(* [comment removed for export] *)
Lemma tailG (fx : FPState) R M model LK Aw (B a0 s3 s5 s7 c n0 p : Z) (cr' : credit) :
  stok model LK Aw -> x = PM.VLong c n0 p -> c <= 44 ->
  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 o -> getr R (reg 9) = Z_to_bv 64 47 -> getr R (reg 10) = Z_to_bv 64 a0 ->
  getr R (reg 18) = Z_to_bv 64 B -> getr R (reg 19) = Z_to_bv 64 s3 -> getr R (reg 20) = Z_to_bv 64 0 -> getr R (reg 21) = Z_to_bv 64 s5 -> getr R (reg 22) = Z_to_bv 64 1 ->
  getr R (reg 23) = Z_to_bv 64 s7 ->
  0 <= a0 < 2 ^ 64 -> 4096 <= s3 <= 140737488355328 -> 0 <= s5 <= 64 -> 0 <= s7 < 2 ^ 64 ->
  kept0 R -> saves M -> mem_ok M -> PMSPA.accA M B 48 ->
  ri_inv HI ((B, 48) :: LB) FF LK cr' Aw M (vml_of model) ->
  PmSpecs.PMSP.credit_keep cr0 cr' (scA (PQMA.pot_textM HV x)) (scA (PQMA.pot_textM HV (PM.VLong 48 0 B))) ->
