Lemma after_newT (fx : FPState) R M model LK Aw (B s2 s7 n0 : Z) :
  stok model LK Aw -> x = PM.VShort n0 ->
  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 o -> getr R (reg 9) = Z_to_bv 64 47 -> getr R (reg 10) = Z_to_bv 64 B ->
  getr R (reg 18) = Z_to_bv 64 s2 -> getr R (reg 19) = Z_to_bv 64 48 -> getr R (reg 20) = Z_to_bv 64 0 -> getr R (reg 21) = Z_to_bv 64 22 -> getr R (reg 22) = Z_to_bv 64 0 ->
  getr R (reg 23) = Z_to_bv 64 s7 -> 0 <= s2 < 2 ^ 64 -> 0 <= s7 < 2 ^ 64 ->
  kept0 R -> saves M -> mem_ok M -> PMSPA.accA M B 48 ->
  ri_inv HI ((B, 48) :: LB) FF LK (adebit L cr0 48) Aw M (vml_of model) ->
  PmSpecs.PMSP.credit_keep cr0 (adebit L cr0 48) (scA (PQMA.pot_textM HV x)) (scA (PQMA.pot_textM HV (PM.VLong 48 0 B))) ->
