  stok model LK Aw -> x = PM.VLong c n0 p -> c <= 44 -> (B + 48 <= p \/ p + c <= B) ->
  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 o -> getr R (reg 9) = Z_to_bv 64 47 -> getr R (reg 10) = Z_to_bv 64 B ->
  getr R (reg 18) = Z_to_bv 64 s2 -> getr R (reg 19) = Z_to_bv 64 48 -> getr R (reg 20) = Z_to_bv 64 0 -> getr R (reg 21) = Z_to_bv 64 s5 -> getr R (reg 22) = Z_to_bv 64 1 ->
